#!/bin/zsh
# 让 Codex 出设置窗口的设计图：先有设计稿，再照着做。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、纯浅灰背景上只放这一个窗口）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 macOS 桌面应用「豆仓」的设置窗口（豆仓连接一颗 AI 录音豆，把录音自动转成文字、整理成纪要和待办）。它是一个标准的 macOS 设置窗口：左上角红黄绿三个圆点，窗口顶部是一排居中的页签，每个页签是一个线条图标加下面的小字，共五个：「通用」「语音输入」「模型」「词库」「连接」，当前选中的页签有浅琥珀色圆角底、图标和文字是琥珀色。窗口宽约 620、内容不需要滚动、一屏放完。设计语言：苹果 macOS 最新系统设置的风格加乔纳森·艾维式的克制——分组圆角卡片、行与行之间细分隔线、左边是标题右边是控件、说明文字是小号灰字、对齐严谨、留白舒服。配色严格限定：暖白纸色背景（#F6F3EC）、卡片是更白一点的暖白、石墨黑文字（#1A1A1A）、唯一强调色琥珀橙（#F2A33A，用在开关、选中的分段和选中的页签）、绿色只用于「已就绪」「已允许」的小勾；绝对不要蓝色、紫色、青色。界面文字全部是简体中文，字体像苹方，文字清晰可读、没有乱码、不要出现英文技术词。"
gen ui_settings_general "【通用页签选中】内容从上到下三组卡片。第一组「外观」：一行三个带小预览图的选项卡片「跟随系统」「浅色」「深色」，浅色被选中（琥珀色描边）。第二组「我是做什么的」：一行「我的职业」右边下拉显示「自媒体创作者」，下面一行小灰字「格外留意能做成选题的观点、可直接引用的金句、有故事性的片段和具体数据。」。第三组「录完之后」：三行带开关，每行有一个小图标、标题和一行小灰字说明：「边录边出字 / 录音时在舞台上实时显示文字」「自动从录音豆下载 / 录完一条就拉到这台 Mac」「自动转写并整理 / 下载后直接出文字稿、纪要和待办」，三个开关都是打开的琥珀色。$S" &
gen ui_settings_models "【模型页签选中】内容从上到下两张大卡片，每张卡片顶部左边是图标和粗体标题，右边是一个状态胶囊。第一张「转写：把声音变成文字」，状态胶囊绿色小勾「已就绪」；卡片里一行「引擎」右边下拉「Qwen3-ASR（本机）」，一行「模型」右边灰字「已下载 · 1.0 GB」，底部小灰字「在这台 Mac 上运行，录音不会上传。」和一个很小的折叠项「高级」。第二张「整理：写纪要、回答提问」，状态胶囊绿色小勾「已就绪」；卡片里先是一个三段分段选择「云端优先」「只用云端」「只用本机」（第一个选中，琥珀色），下面分左右两小块：左块「本机模型」写「Qwen3 4B 已就绪」和小按钮「打开模型文件夹」，右块「云端服务」写「DeepSeek · deepseek-chat」和小按钮「更改…」「测试」。底部小灰字「本机模型不联网；云端纪要质量更高，但文字稿会发给服务商，录音本身不会。」。$S" &
wait
